CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS organization(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),name TEXT NOT NULL,department TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS funder(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunity(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),funder_id TEXT NOT NULL REFERENCES funder(id),title TEXT NOT NULL,due_date TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','application','submitted','awarded','declined','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS source_document(id TEXT PRIMARY KEY,opportunity_id TEXT NOT NULL REFERENCES opportunity(id),filename TEXT NOT NULL,mime_type TEXT NOT NULL,storage_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL DEFAULT 'application',parser TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS application_requirement(id TEXT PRIMARY KEY,opportunity_id TEXT NOT NULL REFERENCES opportunity(id),source_document_id TEXT NOT NULL REFERENCES source_document(id),text TEXT NOT NULL,category TEXT NOT NULL,suggested_department TEXT NOT NULL,department TEXT NOT NULL,owner_id TEXT REFERENCES users(id),due_date TEXT,status TEXT NOT NULL CHECK(status IN ('Not started','In progress','Waiting','Already available','Ready','Complete','Not applicable')),review_state TEXT NOT NULL CHECK(review_state IN ('Proposed','Accepted','Rejected','Edited')),source_page INTEGER,source_section TEXT,source_excerpt TEXT NOT NULL,confidence REAL CHECK(confidence BETWEEN 0 AND 1),original_suggestion TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',reviewed_by TEXT REFERENCES users(id),reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS review_event(id TEXT PRIMARY KEY,requirement_id TEXT NOT NULL REFERENCES application_requirement(id),user_id TEXT NOT NULL REFERENCES users(id),before_json TEXT NOT NULL,after_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submitted_commitment(id TEXT PRIMARY KEY,opportunity_id TEXT NOT NULL REFERENCES opportunity(id),source_document_id TEXT NOT NULL REFERENCES source_document(id),text TEXT NOT NULL,category TEXT NOT NULL,review_state TEXT NOT NULL DEFAULT 'Proposed' CHECK(review_state IN ('Proposed','Accepted','Rejected','Edited')),source_page INTEGER,source_section TEXT,source_excerpt TEXT NOT NULL,confidence REAL CHECK(confidence BETWEEN 0 AND 1));
CREATE TABLE IF NOT EXISTS award(id TEXT PRIMARY KEY,opportunity_id TEXT NOT NULL REFERENCES opportunity(id),amount_minor INTEGER,currency TEXT NOT NULL DEFAULT 'USD',starts_on TEXT,ends_on TEXT);
CREATE TABLE IF NOT EXISTS award_condition(id TEXT PRIMARY KEY,award_id TEXT NOT NULL REFERENCES award(id),source_document_id TEXT NOT NULL REFERENCES source_document(id),text TEXT NOT NULL,category TEXT NOT NULL,review_state TEXT NOT NULL DEFAULT 'Proposed' CHECK(review_state IN ('Proposed','Accepted','Rejected','Edited')),source_page INTEGER,source_section TEXT,source_excerpt TEXT NOT NULL,confidence REAL CHECK(confidence BETWEEN 0 AND 1));
CREATE TABLE IF NOT EXISTS obligation(id TEXT PRIMARY KEY,award_id TEXT NOT NULL REFERENCES award(id),commitment_id TEXT REFERENCES submitted_commitment(id),condition_id TEXT REFERENCES award_condition(id),text TEXT NOT NULL,category TEXT NOT NULL,department TEXT,owner_id TEXT REFERENCES users(id),due_date TEXT,trigger_text TEXT,evidence_requirement TEXT,evidence_link TEXT,status TEXT NOT NULL DEFAULT 'Not started',verified_by TEXT NOT NULL REFERENCES users(id),verified_at TEXT NOT NULL,CHECK((commitment_id IS NOT NULL) != (condition_id IS NOT NULL)));
CREATE TRIGGER IF NOT EXISTS verify_condition BEFORE INSERT ON obligation WHEN NEW.condition_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM award_condition c JOIN award a ON a.id=c.award_id WHERE c.id=NEW.condition_id AND c.award_id=NEW.award_id AND c.review_state IN ('Accepted','Edited')) THEN RAISE(ABORT,'Condition must be verified and belong to award') END; END;
CREATE TRIGGER IF NOT EXISTS verify_commitment BEFORE INSERT ON obligation WHEN NEW.commitment_id IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM submitted_commitment c JOIN award a ON a.opportunity_id=c.opportunity_id WHERE c.id=NEW.commitment_id AND a.id=NEW.award_id AND c.review_state IN ('Accepted','Edited')) THEN RAISE(ABORT,'Commitment must be verified and belong to opportunity') END; END;
CREATE INDEX IF NOT EXISTS requirement_opportunity ON application_requirement(opportunity_id);
